import { AgentContextError } from '../../../../application/mapping/agent/agentContextService';
import type { IncomingMessage } from 'node:http';
import type { Duplex } from 'node:stream';
import { WebSocket, WebSocketServer } from 'ws';
import { LiveCanvasError, type LiveCanvasService } from '../../../../application/mapping/agent/liveCanvasService';
import { liveCanvasMessageSchema, type LiveCanvasEvent } from '../../../../domain/mapping/agent/liveCanvasStatus';
import { sendJson } from '../../http/http';
import type { Connect } from 'vite';
import type { ServerResponse } from 'node:http';

export async function readShortContext(request: Connect.IncomingMessage, response: ServerResponse, url: URL, service: LiveCanvasService) {
  response.setHeader('cache-control', 'no-store');
  if (request.method !== 'GET') return sendJson(response, 405, { error: 'method not allowed' });
  const workspaceInstanceId = url.searchParams.get('workspaceInstanceId'), documentId = url.searchParams.get('documentId');
  if (!workspaceInstanceId || workspaceInstanceId.length > 200 || !documentId || documentId.length > 200
    || url.searchParams.getAll('workspaceInstanceId').length !== 1 || url.searchParams.getAll('documentId').length !== 1)
    return sendJson(response, 400, { code: 'INVALID_REQUEST', error: 'Provide one workspaceInstanceId and one documentId (1–200 characters each)' });
  try {
    const context = await service.shortContextForCanvas(workspaceInstanceId, documentId);
    response.setHeader('X-Canvas-Epoch', context.canvasEpoch);
    response.setHeader('X-Document-Version', String(context.version));
    return sendJson(response, 200, context);
  } catch (error) {
    if (error instanceof LiveCanvasError) return sendJson(response, error.status, { code: error.code, error: error.message });
    const message = error instanceof Error ? error.message : String(error);
    return sendJson(response, 503, { code: 'CONTEXT_UNAVAILABLE', error: message });
  }
}

export function readLiveSelection(request: Connect.IncomingMessage, response: ServerResponse, connectionId: string, service: LiveCanvasService) {
  response.setHeader('cache-control', 'private, no-cache');
  if (request.method !== 'GET') return sendJson(response, 405, { error: 'method not allowed' });
  try {
    const selection = service.read(connectionId);
    response.setHeader('X-Canvas-Epoch', selection.canvasEpoch);
    response.setHeader('X-Selection-Sequence', String(selection.sequence));
    response.setHeader('X-Document-Version', String(selection.documentVersion));
    response.setHeader('X-Selection-Received-At', selection.receivedAt);
    const etag = `"${selection.connectionId}:${selection.sequence}"`;
    response.setHeader('etag', etag);
    const matches = request.headers['if-none-match']?.split(',').some(tag => tag.trim().replace(/^W\//, '') === etag || tag.trim() === '*');
    if (matches) { response.statusCode = 304; response.end(); return; }
    sendJson(response, 200, selection);
  } catch (error) {
    if (!(error instanceof LiveCanvasError)) throw error;
    sendJson(response, error.status, { code: error.code, error: error.message });
  }
}

/** One endpoint; the first frame either attaches an external reader or registers a browser publisher. */
type UpgradeListener = (request: IncomingMessage, socket: Duplex, head: Buffer) => void;
interface UpgradeServer {
  on(event: 'upgrade', listener: UpgradeListener): unknown;
  off(event: 'upgrade', listener: UpgradeListener): unknown;
}

export function attachLiveCanvasSockets(server: UpgradeServer, service: LiveCanvasService, options: { agentContextUploadsEnabled?: boolean } = {}) {
  const sockets = new WebSocketServer({ noServer: true, maxPayload: 8 * 1024 * 1024, perMessageDeflate: false });
  const alive = new Set<WebSocket>();
  sockets.on('connection', ws => {
    alive.add(ws);
    let workspaceInstanceId: string | undefined, connectionId: string | undefined;
    let contextPending = false, attaching = false, contextAllowance = 0;
    const send = (event: LiveCanvasEvent) => {
      if (ws.readyState !== WebSocket.OPEN) return;
      // Deltas cannot be dropped/coalesced independently. Bound the transport queue
      // and force slow readers to reconnect for an authoritative snapshot instead.
      if (ws.bufferedAmount > 64 * 1024 + contextAllowance) { ws.close(1013, 'Reader too slow; reconnect for snapshot'); return; }
      const encoded = JSON.stringify(event);
      const hasContext = event.type === 'context.snapshot' || event.type === 'attached' && event.context !== undefined;
      if (hasContext) {
        const bytes = Buffer.byteLength(encoded);
        if (bytes > 64 * 1024 * 1024) { ws.close(1009, 'Canvas context exceeds 64 MiB transport limit'); return; }
        contextAllowance += bytes;
        ws.send(encoded, () => { contextAllowance -= bytes; });
      } else ws.send(encoded);
    };
    let handshake = setTimeout(() => { if (!connectionId && !workspaceInstanceId) ws.close(1008, 'Attach required'); }, 10_000);
    ws.on('pong', () => alive.add(ws));
    ws.on('error', () => ws.terminate());
    ws.on('message', async (raw, binary) => {
      let requestId: string | undefined;
      try {
        if (binary) throw new LiveCanvasError('INVALID_MESSAGE', 400, 'Expected a JSON text frame');
        const decoded: unknown = JSON.parse(raw.toString());
        if (decoded && typeof decoded === 'object' && 'requestId' in decoded
          && typeof decoded.requestId === 'string' && decoded.requestId.length <= 200) requestId = decoded.requestId;
        const message = liveCanvasMessageSchema.parse(decoded);
        if (options.agentContextUploadsEnabled !== true && message.type === 'agent-context.upload') {
          throw new LiveCanvasError('HTTP_WRITES_DISABLED', 403, 'Agent context uploads are disabled; start the server with --http to enable them.');
        }
        if (message.type === 'attach' || message.type === 'publish') {
          if (connectionId || workspaceInstanceId || attaching) throw new LiveCanvasError('ALREADY_ATTACHED', 409, 'Open another socket to bind another canvas');
          if (message.type === 'attach') {
            attaching = true;
            let context;
            try {
              if (message.includeContext) {
                clearTimeout(handshake);
                handshake = setTimeout(() => ws.close(1008, 'Canvas context timed out'), 30_000);
                context = await service.contextForCanvas(message.workspaceInstanceId, message.documentId);
              }
            } finally { attaching = false; }
            if (ws.readyState !== WebSocket.OPEN) return;
            const initial = service.attach(message.workspaceInstanceId, message.documentId, send);
            connectionId = initial.connectionId;
            send({ type: 'attached', ...initial, ...(context ? { context } : {}) });
          } else {
            service.publish(ws, message.workspaceInstanceId, send);
            workspaceInstanceId = message.workspaceInstanceId;
            send({ type: 'publisher.ready', protocolVersion: 2 });
          }
          clearTimeout(handshake);
        } else if (message.type === 'agent-context.upload') {
          if (!connectionId) throw new LiveCanvasError('READER_REQUIRED', 403);
          const { type: _, requestId: uploadRequestId, ...trajectory } = message;
          send({ type: 'agent-context.uploaded', requestId: uploadRequestId, connectionId,
            ...service.uploadAgentContext(connectionId, uploadRequestId, trajectory) });
        } else if (message.type === 'context.get') {
          requestId = message.requestId;
          if (!connectionId) throw new LiveCanvasError('READER_REQUIRED', 403);
          if (contextPending || contextAllowance > 0) throw new LiveCanvasError('CONTEXT_BUSY', 409, 'Wait for the pending context request');
          contextPending = true;
          try { send({ type: 'context.snapshot', requestId, ...await service.context(connectionId) }); }
          finally { contextPending = false; }
        } else {
          if (!workspaceInstanceId) throw new LiveCanvasError('PUBLISHER_REQUIRED', 403);
          if (message.type === 'remove') service.remove(ws, workspaceInstanceId, message.documentId, message.canvasEpoch);
          else {
            const { type: _, ...selection } = message;
            service.update(ws, workspaceInstanceId, selection);
          }
        }
      } catch (error) {
        send({ type: 'error', ...(requestId ? { requestId } : {}), code: error instanceof LiveCanvasError || error instanceof AgentContextError ? error.code : 'INVALID_MESSAGE',
          error: error instanceof Error ? error.message : String(error) });
      }
    });
    ws.on('close', () => {
      clearTimeout(handshake); alive.delete(ws);
      if (connectionId) service.detach(connectionId);
      if (workspaceInstanceId) service.disconnect(ws, workspaceInstanceId);
    });
  });
  const upgrade: UpgradeListener = (request, socket, head) => {
    if (new URL(request.url ?? '/', 'http://localhost').pathname !== '/api/mapping/live') return;
    // Native clients may omit Origin. Browser clients must belong to this app's origin.
    let allowed = !request.headers.origin;
    try { allowed ||= new URL(request.headers.origin!).host === request.headers.host; } catch { /* invalid origin */ }
    if (!allowed || sockets.clients.size >= 1024) {
      socket.end(`HTTP/1.1 ${allowed ? '503 Service Unavailable' : '403 Forbidden'}\r\nConnection: close\r\n\r\n`); return;
    }
    sockets.handleUpgrade(request, socket, head, ws => sockets.emit('connection', ws, request));
  };
  server.on('upgrade', upgrade);
  const heartbeat = setInterval(() => {
    for (const ws of sockets.clients) {
      if (!alive.delete(ws)) ws.terminate(); else ws.ping();
    }
  }, 15_000);
  heartbeat.unref();
  return () => {
    clearInterval(heartbeat); server.off('upgrade', upgrade);
    for (const ws of sockets.clients) ws.terminate();
    sockets.close();
  };
}

sources.tests/browser/mapping/browser-change-acc:
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { DiagramStore } from '../../../infrastructure/core/persistence/store.ts';
import { DiagramChangeSessionStore } from '../../../infrastructure/mapping/changes/diagramChangeSessionStore.ts';
import { ChangeSessionService } from '../../../application/mapping/changes/changeSessionService.ts';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'acceptance-browser-'));
let server;
try {
  // Disposable fixture setup happens before the server or browser starts.
  await seedMappingFixture(root, { ascii: 'Root\n|-- Before acceptance\n`-- Keep', nodes: [] });
  const store = new DiagramStore(root), repository = new DiagramChangeSessionStore(store.storeRoot);
  const bridge = { list: () => [] };
  const changes = new ChangeSessionService(repository, store, bridge);
  const proposal = await changes.create({ title: 'Acceptance browser fixture', requestId: 'fixture-create' });
  const changeSessionId = proposal.changeSessionId, documentId = proposal.documents[0].documentId;
  await changes.apply(changeSessionId, documentId, 0, [{ method: 'patchDiagram', nodeId: 'grid:overview', start: 2, end: 2, patch: '|-- After acceptance' }], 'fixture-edit');
  const draft = await changes.get(changeSessionId);
  await changes.update({ changeSessionId, expectedVersion: draft.version, requestId: 'fixture-ready', status: 'ready' });
  const port = await new Promise(resolve => { const socket = createServer(); socket.listen(0, '127.0.0.1', () => { const port = socket.address().port; socket.close(() => resolve(port)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { cwd: process.cwd(), env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: store.storeRoot, NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'ignore', 'pipe'] });
  let serverErrors = ''; server.stderr.on('data', chunk => { serverErrors += chunk; });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 }).catch(error => { throw new Error(`${error}\n${serverErrors}`); });
  await withHeadlessBrowser({ url: `${url}/mapping`, width: 1800, height: 1100, chromePath: process.env.CHROME_PATH,
    arguments: ['--disable-gpu', ...(process.platform === 'linux' ? ['--no-sandbox'] : [])] }, async ({ cdp }) => {
    const send = cdp.send.bind(cdp);
    cdp.send = async (method, params) => {
      let timer;
      try { return await Promise.race([send(method, params), new Promise((_, reject) => { timer = setTimeout(() => reject(Error(`CDP timed out: ${method}`)), 30000); })]); }
      finally { clearTimeout(timer); }
    };
    const errors = [];
    await cdp.send('Page.enable');
    cdp.on('Page.javascriptDialogOpening', () => void cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    await cdp.send('Runtime.enable'); cdp.on('Runtime.exceptionThrown', event => errors.push(event.exceptionDetails.text));
    const canvasReplies = [];
    const changeReads = [];
    cdp.on('Fetch.requestPaused', event => {
      changeReads.push(event.request.url);
      void cdp.send('Fetch.continueRequest', { requestId: event.requestId });
    });
    await cdp.send('Fetch.enable', { patterns: [{ urlPattern: '*/api/mapping/agent/change-sessions*' }] });
    await cdp.send('Network.enable');
    cdp.on('Network.requestWillBeSent', ({ request }) => {
      if (request.url.includes('/canvases/') && request.url.endsWith('/reply') && request.postData)
        canvasReplies.push(JSON.parse(request.postData));
    });
    const click = async (selector, text) => {
      let point;
      await waitFor(async () => {
        point = await evaluate(cdp, `(() => { const el = [...document.querySelectorAll(${JSON.stringify(selector)})].find(el => !el.disabled && ${text ? `el.textContent.includes(${JSON.stringify(text)})` : 'true'}); if (!el) return null; const r=el.getBoundingClientRect(); return r.width && r.height ? {x:r.x+r.width/2,y:r.y+r.height/2}:null; })()`);
        return !!point;
      });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', button: 'left', clickCount: 1, ...point });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', button: 'left', clickCount: 1, ...point });
    };
    const visibleCanvasText = () => evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden])')?.textContent ?? ''`);
    await waitFor(async () => (await visibleCanvasText()).includes('Before acceptance'));
    await click('[role="tab"]', 'Changes');
    await click('nav[aria-label="Diagram changes"] summary', 'Acceptance browser fixture');
    await click('nav[aria-label="Diagram changes"] button', 'Current LLM prompt stack');
    await waitForSelector(cdp, '[data-diff-status="modified"]');
    await waitFor(() => changeReads.some(url => url.includes('/preview?')));
    assert.ok(!changeReads.some(url => url.endsWith(`/change-sessions/${changeSessionId}`)), 'Opening a preview must not request the full session');
    await waitFor(() => changeReads.some(url => url.includes('/preview?') && new URL(url).searchParams.has('version')));
    const scoped = await fetch(`${url}/api/mapping/agent/change-sessions/${changeSessionId}/preview?documentId=${documentId}`).then(r => r.json());
    assert.equal(scoped.document.id, documentId);
    assert.ok(!('history' in scoped.document) && !('past' in scoped.document) && !('receipts' in scoped));
    assert.equal(await fetch(`${url}/api/mapping/agent/change-sessions/${changeSessionId}/preview?documentId=${documentId}&version=${scoped.version}`).then(r => r.json()), null);
    console.log('Scoped preview rendered; accepting');
    canvasReplies.length = 0;
    await click('.change-session-actions button', 'Accept all changes');
    await waitFor(async () => (await visibleCanvasText()).includes('After acceptance'));
    const stateReplies = canvasReplies.filter(reply => reply.value?.document);
    assert.ok(stateReplies.length > 0, 'acceptance checked the live browser state');
    for (const reply of stateReplies)
      assert.deepEqual(Object.keys(reply.value).sort(), ['document', 'name'], 'acceptance does not transfer history or rendering metadata');
    assert.equal(await evaluate(cdp, '!!document.querySelector("[data-change-session]")'), false);
    assert.equal(await evaluate(cdp, '!!document.querySelector("[data-diff-status]")'), false);
    const accepted = await changes.get(changeSessionId);
    assert.equal(accepted.status, 'accepted');
    assert.ok(accepted.acceptance.documents[0].before.checkpointId);
    // Wait for the public workspace autosave to contain the new published head.
    await waitFor(async () => {
      const response = await fetch(`${url}/api/mapping/workspace`);
      if (!response.ok) return false;
      return JSON.stringify(await response.json()).includes(accepted.acceptance.documents[0].after.revisionId);
    });
    await cdp.send('Page.reload', { ignoreCache: true });
    console.log('Reloading accepted canvas');
    await waitFor(async () => (await visibleCanvasText()).includes('After acceptance'));
    await click('[role="tab"]', 'Changes');
    await click('nav[aria-label="Diagram changes"] summary', 'Acceptance browser fixture');
    await click('nav[aria-label="Diagram changes"] button', 'Current LLM prompt stack');
    await waitForSelector(cdp, '[data-diff-status="modified"]');
    assert.ok(await evaluate(cdp, 'document.querySelector(".change-session-actions").textContent.includes("Accepted")'));
    assert.equal(await evaluate(cdp, '[...document.querySelectorAll(".change-session-actions button")].some(b=>b.textContent.includes("Accept all"))'), false);
    const previewCount = changeReads.filter(url => url.includes('/preview?')).length;
    const listCount = changeReads.filter(url => url.endsWith('/change-sessions')).length;
    await waitFor(() => changeReads.filter(url => url.endsWith('/change-sessions')).length >= listCount + 2);
    assert.equal(changeReads.filter(url => url.includes('/preview?')).length, previewCount, 'Accepted previews stop polling while the explorer continues refreshing summaries');
    await click('.change-session-actions button', 'Open canvas');
    await waitFor(async () => (await visibleCanvasText()).includes('After acceptance'));
    await click('.mapping-document-view:not([hidden]) button', 'Undo');
    await waitFor(async () => (await visibleCanvasText()).includes('Before acceptance'));
    // Reopening the accepted review must not discard a later local undo/edit.
    await click('[role="tab"]', 'Changes');
    await click('nav[aria-label="Diagram changes"] summary', 'Acceptance browser fixture');
    await click('nav[aria-label="Diagram changes"] button', 'Current LLM prompt stack');
    await waitForSelector(cdp, '.change-session-actions');
    await click('.change-session-actions button', 'Open canvas');
    await waitFor(async () => (await visibleCanvasText()).includes('Before acceptance'));
    assert.deepEqual(errors, []);
    console.log('PASS: accept -> published canvas without diff -> reload -> retained review diff -> undo restores original');
  });
} finally {
  if (server && server.exitCode === null) {
    server.kill('SIGTERM');
    await new Promise(resolve => server.once('exit', resolve));
  }
  await rm(root, { recursive: true, force: true });
}

sources.tests/browser/mapping/browser-diagram-ed:
// Run after npm run build: node --import tsx tests/browser/mapping/browser-diagram-edit-ui-check.mjs
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { canvasSaveFixture } from '../../support/mappingDiagram.ts';
import { RevisionedDiagramService } from '../../../domain/core/diagrams/diagramService.ts';
import { singleDiagramScene, projectCanvasSnapshot } from '../../../domain/core/diagrams/projectDiagramCanvas.ts';
import { asciiSha256 } from '../../../domain/core/diagrams/asciiSha256.ts';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'diagram-edit-ui-'));
let server;
try {
  await seedMappingFixture(root, { ascii: 'First\n`-- Existing', nodes: [] });
  const catalogPath = path.join(root, '.diagrams/representations/catalog.json');
  const catalog = JSON.parse(await readFile(catalogPath, 'utf8'));
  const scene = singleDiagramScene('First\n`-- Existing');
  const diagrams = new RevisionedDiagramService();
  scene.contents = { ...scene.contents,
    overview: diagrams.create({ id: 'overview', revision: 0, ascii: 'First\n`-- Existing', structureKind: 'tree' }).diagram,
    second: diagrams.create({ id: 'second', revision: 0, ascii: 'Second\n`-- Other', structureKind: 'tree' }).diagram };
  scene.root.children.push({ id: 'second', kind: 'diagram', contentId: 'second', position: { column: 35, row: 0 }, collapsed: false });
  const revision = catalog.revisions['revision-overview'];
  revision.content = { kind: 'canvas-history', history: canvasSaveFixture({ name: 'Fixture', scene }).history };
  revision.ascii = projectCanvasSnapshot(scene).ascii; revision.asciiSha256 = asciiSha256(revision.ascii);
  await writeFile(catalogPath, JSON.stringify(catalog));
  const port = await new Promise(resolve => { const s = createServer(); s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => resolve(p)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { detached: true, env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: path.join(root, '.diagrams'), NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'ignore', 'pipe'] });
  let errors = ''; server.stderr.on('data', c => { errors += c; });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 }).catch(e => { throw Error(`${e}\n${errors}`); });
  await withHeadlessBrowser({ url: `${url}/mapping?diagram=representation-overview`, width: 1800, height: 1100,
    chromePath: process.env.CHROME_PATH, arguments: ['--no-sandbox', '--disable-gpu'] }, async ({ cdp }) => {
    await cdp.send('Page.enable');
    await cdp.send('Network.enable');
    let editRequests = 0;
    cdp.on('Network.requestWillBeSent', event => { if (event.request.url.endsWith('/tools/edit-diagram')) editRequests++; });
    cdp.on('Page.javascriptDialogOpening', () => void cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    const send = cdp.send.bind(cdp);
    cdp.send = async (method, parameters) => {
      let timer;
      try { return await Promise.race([send(method, parameters), new Promise((_, reject) => { timer = setTimeout(() => reject(Error(`CDP timeout: ${method}`)), 15000); })]); }
      finally { clearTimeout(timer); }
    };
    const mouse = async (type, p, clickCount = 1, modifiers = 0) => cdp.send('Input.dispatchMouseEvent', { type, ...p, button: 'left', buttons: type === 'mouseReleased' ? 0 : 1, clickCount, modifiers });
    const click = async (selector, text) => {
      const p = await evaluate(cdp, `(() => { const e=[...document.querySelectorAll(${JSON.stringify(selector)})].find(e=>!${JSON.stringify(text)} || e.textContent.trim()===${JSON.stringify(text)}); if (!e || e.disabled) throw Error('Unavailable: '+${JSON.stringify(text ?? selector)}); const r=e.getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);
      await mouse('mousePressed', p); await mouse('mouseReleased', p);
    };
    const diagramPoint = async id => evaluate(cdp, `(() => {const r=document.querySelector('[data-grid-box="${id}"]').getBoundingClientRect();return{x:r.x+8,y:r.y+8};})()`);
    const select = async id => { const p = await diagramPoint(id); await mouse('mousePressed', p, 2, 2); await mouse('mouseReleased', p, 2, 2); };
    const text = async () => evaluate(cdp, "[...document.querySelectorAll('[data-native-node] .mapping-poc-ascii')].map(el => el.textContent).join('\\n')");
    const historyKey = async key => {
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key, code: `Key${key.toUpperCase()}`, modifiers: 2, windowsVirtualKeyCode: key.toUpperCase().charCodeAt(0) });
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key, code: `Key${key.toUpperCase()}`, modifiers: 2, windowsVirtualKeyCode: key.toUpperCase().charCodeAt(0) });
    };
    await waitForSelector(cdp, '[data-grid-box=second]');
    await waitFor(async () => (await diagramPoint('overview')).x > 320);
    await select('overview'); await waitForSelector(cdp, '.mapping-diagram-selection-actions');
    await select('second');
    await waitFor(async () => evaluate(cdp, "[...document.querySelectorAll('.mapping-diagram-selection-actions button')].find(e=>e.textContent==='Update diagram with AI…')?.disabled"));
    await select('second');
    await click('.mapping-diagram-selection-actions button', 'Update diagram with AI…');
    await waitForSelector(cdp, '#diagram-edit-prompt');
    for (const action of ['Close', 'Cancel', 'Escape']) {
      await cdp.send('Input.insertText', { text: 'Changed my mind' });
      if (action === 'Escape') {
        await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
        await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
      } else await click('.diagram-edit-composer button', action);
      await waitFor(async () => !await evaluate(cdp, "Boolean(document.querySelector('.diagram-edit-composer, .diagram-edit-launcher'))"));
      assert.equal(editRequests, 0, 'Dismissing a prompt must not start generation');
      await click('.mapping-diagram-selection-actions button', 'Update diagram with AI…');
      await waitForSelector(cdp, '#diagram-edit-prompt');
      assert.equal(await evaluate(cdp, "document.querySelector('#diagram-edit-prompt').value"), '');
    }
    await cdp.send('Input.insertText', { text: 'UI whole diagram update' });
    await select('second');
    assert.ok(await evaluate(cdp, "document.querySelector('.diagram-edit-target').textContent.includes('/ First')"));
    await click('.diagram-edit-composer button[type=submit]');
    await waitForSelector(cdp, '[data-edit-status=completed]', { timeoutMs: 15000 });
    assert.ok((await text()).includes('[edited: UI whole diagram update]'));
    await captureScreenshot(cdp, { output: process.env.UI_SCREENSHOT_PATH ?? path.join(root, 'completed.png') });
    await click('[aria-label="Close diagram update"]');
    await waitFor(async () => !await evaluate(cdp, "Boolean(document.querySelector('.diagram-edit-composer, .diagram-edit-launcher'))"));
    console.log('PASS: Close/Cancel/Escape discard drafts without requests; completed updates dismiss; whole selection, multi-selection guard, pinned target and persistence acknowledgement');
    // Reload immediately after completion: no explicit Save action.
    let loaded = false; cdp.on('Page.loadEventFired', () => { loaded = true; });
    await cdp.send('Page.reload', { ignoreCache: true }); await waitFor(() => loaded);
    await waitForSelector(cdp, '[data-grid-box=overview]');
    await waitFor(async () => (await text()).includes('[edited: UI whole diagram update]'));
    assert.equal(await evaluate(cdp, "Boolean(document.querySelector('.diagram-edit-composer'))"), false);
    await click('.mapping-grid-tools > span');
    await historyKey('z');
    await waitFor(async () => !(await text()).includes('[edited: UI whole diagram update]'));
    await historyKey('y');
    await waitFor(async () => (await text()).includes('[edited: UI whole diagram update]'));
    // A normal text input keeps its own native undo/redo; it must not navigate canvas history.
    await click('input[placeholder="Find a diagram…"]');
    await cdp.send('Input.insertText', { text: 'Test filter' });
    await historyKey('z');
    await waitFor(async () => await evaluate(cdp, "document.querySelector('input[placeholder=\"Find a diagram…\"]').value === ''"));
    assert.ok((await text()).includes('[edited: UI whole diagram update]'));
    await historyKey('y');
    await waitFor(async () => await evaluate(cdp, "document.querySelector('input[placeholder=\"Find a diagram…\"]').value === 'Test filter'"));
    assert.ok((await text()).includes('[edited: UI whole diagram update]'));
    await historyKey('z');
    // Ctrl-drag part of the other diagram to expose the region action menu.
    await click('.mapping-diagram-selection-actions button', 'Deselect (Esc)');
    const start = await diagramPoint('second');
    const end = { x: start.x + 40, y: start.y + 22 };
    await mouse('mousePressed', start, 1, 2);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...end, button: 'left', buttons: 1, modifiers: 2 });
    await mouse('mouseReleased', end, 1, 2);
    await waitForSelector(cdp, '.retained-selection-controls');
    await click('.retained-selection-controls button', 'Actions (A)');
    await waitForSelector(cdp, '.mapping-poc-selection-actions');
    await click('.mapping-poc-selection-actions button', 'Update containing diagram with AI…');
    await waitForSelector(cdp, '#diagram-edit-prompt');
    assert.ok(await evaluate(cdp, "document.querySelector('.diagram-edit-target').textContent.includes('/ Second')"));
    assert.ok(await evaluate(cdp, "document.querySelector('.diagram-edit-target').textContent.includes('whole diagram')"));
    await cdp.send('Input.insertText', { text: 'UI region owner update' });
    await click('.diagram-edit-composer button[type=submit]');
    await waitForSelector(cdp, '[data-edit-status=completed]', { timeoutMs: 15000 });
    assert.ok((await text()).includes('[edited: UI region owner update]'));
    assert.ok((await text()).includes('[edited: UI whole diagram update]'));
    console.log('PASS: immediate reload, Ctrl+Z/Ctrl+Y canvas undo/redo, native text undo/redo, Ctrl-selection action, whole-owner scope, unmapped diagram update');
  });
} finally {
  if (server?.pid) { try { process.kill(-server.pid, 'SIGTERM'); } catch {} }
  await rm(root, { recursive: true, force: true });
}

